#include <iostream>
#include <iomanip>

int main() {
    int item_id = 0;
    double price = 0.0;
    char category = '\0';

    if (std::cin >> item_id >> price) {
        std::cin.ignore(1);
        std::cin.get(category);

        std::cout << "EXPENSES" << "\n";
        std::cout << "========" << "\n";
        std::cout << std::fixed << std::setprecision(2);
        std::cout << "Item:" << std::setw(10) << item_id << "\n";
        std::cout << "Cost:" << std::setw(10) << price << "\n";
        std::cout << "Cat: " << std::setw(10) << category << "\n";
    }
    return 0;
}

#include <cstdio>

int main() {
    int i = 0;
    double val = 0.0;
    char tag[16];

    if (std::scanf("%d %lf %15s", &i, &val, tag) == 3) {
        std::printf("ID: %+05d\n", i);
        std::printf("Val: %8.2f %%\n", val);
        std::printf("Tag: %-10s\n", tag);
    }
    return 0;
}
